import { syncedSignal } from '@pyreon/sync'
import { connectViaWebSocket, createYjsDoc, persistViaIndexedDB, syncedList } from '@pyreon/sync/yjs'

function openBoard(room: string, token: string) {
  const doc = createYjsDoc()
  persistViaIndexedDB(doc, room) // edits survive reloads and offline
  const ws = connectViaWebSocket(doc, `ws://localhost:1234/${room}?token=${token}`)

  const title = syncedSignal({ doc, key: 'title', initial: 'Untitled' }) // a signal
  const cards = syncedList<string>(doc, 'cards') // a Signal<string[]>, merged by position
  return { title, cards, ws }
}
